package com.lia.mediaplayer.core.testing;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import java.util.concurrent.TimeUnit;

/**
 * Media generated by the test machine's own ffmpeg, so tests need no network and no binary
 * files in the repository. Only encoders built into every ffmpeg are used (MPEG-4 part 2 and
 * FLAC in Matroska).
 *
 * <p>Integration tests call {@link #ffmpeg()} first and skip themselves when it is empty.
 */
public final class TestMedia {

    private static final Optional<Path> FFMPEG = locate("ffmpeg", "FFMPEG_PATH");
    private static final Optional<Path> FFPROBE = locate("ffprobe", "FFPROBE_PATH");

    private TestMedia() {}

    public static Optional<Path> ffmpeg() {
        return FFMPEG;
    }

    public static Optional<Path> ffprobe() {
        return FFPROBE;
    }

    /** {@code seconds} of a moving test pattern and a 440 Hz tone, {@code width × height} at 30 fps. */
    public static Path audioVideo(Path dir, String name, int width, int height, int seconds) throws IOException {
        return generate(
                dir.resolve(name),
                List.of(
                        "-f",
                        "lavfi",
                        "-i",
                        "testsrc2=size=" + width + "x" + height + ":rate=30",
                        "-f",
                        "lavfi",
                        "-i",
                        "sine=frequency=440:sample_rate=48000",
                        "-t",
                        Integer.toString(seconds),
                        "-c:v",
                        "mpeg4",
                        "-q:v",
                        "6",
                        "-g",
                        "15",
                        "-c:a",
                        "flac",
                        "-ac",
                        "2"));
    }

    /** A picture without sound. */
    public static Path videoOnly(Path dir, String name, int width, int height, int seconds) throws IOException {
        return generate(
                dir.resolve(name),
                List.of(
                        "-f",
                        "lavfi",
                        "-i",
                        "testsrc2=size=" + width + "x" + height + ":rate=30",
                        "-t",
                        Integer.toString(seconds),
                        "-c:v",
                        "mpeg4",
                        "-q:v",
                        "6",
                        "-g",
                        "15"));
    }

    /** Sound without a picture. */
    public static Path audioOnly(Path dir, String name, int seconds) throws IOException {
        return generate(
                dir.resolve(name),
                List.of(
                        "-f",
                        "lavfi",
                        "-i",
                        "sine=frequency=330:sample_rate=48000",
                        "-t",
                        Integer.toString(seconds),
                        "-ac",
                        "2",
                        "-c:a",
                        "flac"));
    }

    private static Path generate(Path target, List<String> arguments) throws IOException {
        if (Files.exists(target)) {
            return target;
        }
        var command = new ArrayList<String>();
        command.add(FFMPEG.orElseThrow(() -> new IOException("ffmpeg is not installed"))
                .toString());
        command.addAll(List.of("-nostdin", "-v", "error", "-y"));
        command.addAll(arguments);
        command.add(target.toString());
        Process process = new ProcessBuilder(command).redirectErrorStream(true).start();
        String output = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
        try {
            if (!process.waitFor(60, TimeUnit.SECONDS) || process.exitValue() != 0) {
                throw new IOException("ffmpeg could not generate " + target + ": " + output);
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IOException(e);
        }
        return target;
    }

    private static Optional<Path> locate(String name, String variable) {
        String override = System.getenv(variable);
        List<String> candidates = override != null && !override.isBlank() ? List.of(override) : List.of(name);
        for (String candidate : candidates) {
            try {
                Process process = new ProcessBuilder(candidate, "-version")
                        .redirectErrorStream(true)
                        .start();
                process.getInputStream().readAllBytes();
                if (process.waitFor(10, TimeUnit.SECONDS) && process.exitValue() == 0) {
                    return Optional.of(Path.of(candidate));
                }
            } catch (IOException e) {
                // Not installed.
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }
        }
        return Optional.empty();
    }
}
